import React from "react";
import { FaBell, FaUser } from "react-icons/fa";

function NavBar() {
  return (
    <nav className="bg-white shadow-md p-4 flex justify-between items-center">
      {/* Left - Logo */}
      <div className="flex items-center space-x-2">
        <img src="/logo.svg" alt="AllMyPet Logo" className="h-8" />
        <span className="font-bold text-xl text-indigo-700">AllMyPet</span>
      </div>

      {/* Middle - Nav Links */}
      <div className="hidden md:flex space-x-6 text-gray-700">
        <a href="#" className="hover:text-indigo-500">Home</a>
        <a href="#" className="hover:text-indigo-500">Adopt</a>
        <a href="#" className="hover:text-indigo-500">Community</a>
        <a href="#" className="hover:text-indigo-500">Raise A Pet</a>
        <a href="#" className="hover:text-indigo-500">Veterinarians</a>
      </div>

      {/* Right - Icons & Buttons */}
      <div className="flex items-center space-x-4">
        {/* Notification Bell */}
        <button className="p-2 rounded-full border border-indigo-400 text-indigo-400 hover:bg-indigo-100">
          <FaBell />
        </button>

        {/* Login/Register Button */}
        <button className="border border-indigo-400 px-4 py-2 rounded-full text-indigo-500 hover:bg-indigo-100 flex items-center">
          <FaUser className="mr-2" />
          Login | Register
        </button>
      </div>
    </nav>
  );
}

export default navBar;
